package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang3.StringUtils#indexOfAnyBut
 */
public class StringUtils_indexOfAnyBut_TriageGen2Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testIndexOfAnyBut_NullStr() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut(null, "abc"));
    }

    @Test
    public void testIndexOfAnyBut_EmptyStr() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_NullSearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", null));
    }

    @Test
    public void testIndexOfAnyBut_EmptySearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", ""));
    }

    @Test
    public void testIndexOfAnyBut_FoundAtStart() {
        // 'z' is not in "abc", so index 0 is returned
        assertEquals(0, StringUtils.indexOfAnyBut("zabc", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_FoundInMiddle() {
        // 'd' is not in "abc", index is 1
        assertEquals(1, StringUtils.indexOfAnyBut("adbc", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_FoundAtEnd() {
        // 'z' is not in "abc", index is 3
        assertEquals(3, StringUtils.indexOfAnyBut("abcz", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_NoneFound() {
        // All characters in str are present in searchChars
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("aabbcc", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_SingleCharMatch() {
        assertEquals(0, StringUtils.indexOfAnyBut("x", "y"));
    }

    @Test
    public void testIndexOfAnyBut_AllCharsInSearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_CaseSensitivity() {
        // 'A' is not in 'abc'
        assertEquals(0, StringUtils.indexOfAnyBut("Abc", "abc"));
    }
}
